//   t: título · d: descripción para Google y para la tarjeta · intro · resumen: ideas clave · pasos: [título, texto]
//   errores: fallos frecuentes · nota (opcional): un aviso final.
// Consejos generales de jardinería: no llevan precios, existencias ni servicios concretos de la empresa.
export const GUIAS = [
  { slug: "riego-en-verano", meses: [6, 7, 8, 9],
    plantas: ["Salvia rosmarinus", "Lavandula angustifolia / dentata", "Pistacia lentiscus", "Teucrium fruticans", "Santolina chamaecyparissus", "Tulbaghia violacea"],
    es: { t: "Cómo regar en verano sin malgastar agua",
      d: "Cuándo, cuánto y cómo regar el jardín en verano en Mallorca: riegos largos y espaciados, goteo, acolchado y plantas agrupadas por sed.",
      intro: "En Mallorca el agua es escasa y el verano, largo. Regar bien no es regar más: es dar el agua justa, en el momento adecuado y donde la planta la aprovecha.",
      resumen: ["Riega al amanecer o al anochecer, nunca a pleno sol.", "Mejor riegos largos y espaciados que un poco cada día.", "El goteo y una capa de acolchado ahorran mucha agua.", "Agrupa las plantas según la sed que tienen."],
      pasos: [
        ["Elige bien la hora", "Riega a primera hora de la mañana o al caer la tarde: a mediodía buena parte del agua se evapora antes de llegar a las raíces. Si puedes elegir, mejor al amanecer, porque las hojas se secan pronto y hay menos hongos."],
        ["Riega menos veces, pero a fondo", "Un riego largo cada varios días empuja las raíces hacia abajo, donde la tierra tarda más en secarse. Un poco de agua cada día las deja en la superficie y hace a la planta más débil ante el calor. Antes de regar, hunde un dedo en la tierra: si a cuatro o cinco centímetros sigue húmeda, espera."],
        ["Pon goteo y un programador", "El goteo lleva el agua a la raíz sin mojar caminos ni hojas. Con un programador riegas de madrugada sin estar pendiente y puedes ajustar los minutos mes a mes: en julio y agosto más, en septiembre ya menos."],
        ["Cubre la tierra", "Una capa de cinco a ocho centímetros de corteza de pino, grava o restos de poda triturados mantiene la tierra fresca, frena la evaporación y evita las malas hierbas que compiten por el agua."],
        ["Agrupa las plantas por sed", "Junta en una zona las que piden poca agua —romero, lavanda, lentisco, olivilla— y en otra las sedientas, cada una con su sector de riego. Así ninguna recibe de más ni de menos. Las macetas van aparte: se secan mucho antes que la tierra del jardín."],
      ],
      errores: ["Regar un poco cada día «por si acaso».", "Dejar el programador igual todo el año.", "Regar el césped a mediodía o con viento."],
      nota: "En años de sequía los ayuntamientos limitan el riego de jardines. Consulta las normas de tu municipio antes de programar." },
    ca: { t: "Com regar a l'estiu sense malgastar aigua",
      d: "Quan, quant i com regar el jardí a l'estiu a Mallorca: regs llargs i espaiats, degoteig, encoixinat i plantes agrupades segons la set.",
      intro: "A Mallorca l'aigua és escassa i l'estiu, llarg. Regar bé no és regar més: és donar l'aigua justa, en el moment adequat i allà on la planta l'aprofita.",
      resumen: ["Rega a trenc d'alba o al capvespre, mai a ple sol.", "Millor regs llargs i espaiats que un poc cada dia.", "El degoteig i una capa d'encoixinat estalvien molta aigua.", "Agrupa les plantes segons la set que tenen."],
      pasos: [
        ["Tria bé l'hora", "Rega a primera hora del matí o quan cau la tarda: a migdia bona part de l'aigua s'evapora abans d'arribar a les arrels. Si pots triar, millor a trenc d'alba, perquè les fulles s'eixuguen aviat i hi ha menys fongs."],
        ["Rega menys vegades, però a fons", "Un reg llarg cada uns quants dies empeny les arrels cap avall, on la terra tarda més a assecar-se. Un poc d'aigua cada dia les deixa a la superfície i fa la planta més feble davant la calor. Abans de regar, enfonsa un dit dins la terra: si a quatre o cinc centímetres encara és humida, espera."],
        ["Posa degoteig i un programador", "El degoteig du l'aigua a l'arrel sense banyar camins ni fulles. Amb un programador regues de matinada sense haver-hi d'estar pendent i pots ajustar els minuts mes a mes: al juliol i a l'agost més, al setembre ja menys."],
        ["Cobreix la terra", "Una capa de cinc a vuit centímetres d'escorça de pi, grava o restes de poda triturades manté la terra fresca, frena l'evaporació i evita les males herbes que competeixen per l'aigua."],
        ["Agrupa les plantes per set", "Posa en una zona les que demanen poca aigua —romaní, lavanda, mata, olivereta— i en una altra les assedegades, cadascuna amb el seu sector de reg. Així cap rep de més ni de menys. Els tests van a part: s'assequen molt abans que la terra del jardí."],
      ],
      errores: ["Regar un poc cada dia «per si de cas».", "Deixar el programador igual tot l'any.", "Regar la gespa a migdia o amb vent."],
      nota: "Els anys de sequera els ajuntaments limiten el reg de jardins. Consulta les normes del teu municipi abans de programar." },
    en: { t: "How to water in summer without wasting water",
      d: "When, how much and how to water your garden in summer in Mallorca: long, spaced-out waterings, drip irrigation, mulch and plants grouped by thirst.",
      intro: "In Mallorca water is scarce and summer is long. Watering well doesn't mean watering more: it means giving the right amount, at the right time, where the plant can use it.",
      resumen: ["Water at dawn or dusk, never in full sun.", "Long, spaced-out waterings beat a little every day.", "Drip irrigation and a layer of mulch save a lot of water.", "Group plants by how thirsty they are."],
      pasos: [
        ["Pick the right time", "Water first thing in the morning or as evening falls: at midday much of the water evaporates before it reaches the roots. If you can choose, dawn is best, because the leaves dry quickly and fungal problems are fewer."],
        ["Water less often, but deeply", "A long watering every few days pushes roots downwards, where the soil takes longer to dry out. A little water every day keeps them near the surface and leaves the plant weaker in the heat. Before watering, push a finger into the soil: if it's still moist four or five centimetres down, wait."],
        ["Install drip irrigation and a timer", "Drip irrigation takes water to the roots without wetting paths or leaves. A timer lets you water before dawn without thinking about it, and you can adjust the minutes month by month: more in July and August, less by September."],
        ["Cover the soil", "A five to eight centimetre layer of pine bark, gravel or shredded prunings keeps the soil cool, slows evaporation and keeps down the weeds that compete for water."],
        ["Group plants by thirst", "Put those that need little water — rosemary, lavender, mastic, shrubby germander — in one area and the thirsty ones in another, each on its own irrigation zone. That way none gets too much or too little. Pots are a separate case: they dry out far faster than garden soil."],
      ],
      errores: ["Watering a little every day “just in case”.", "Leaving the timer on the same setting all year.", "Watering the lawn at midday or in the wind."],
      nota: "In drought years town councils restrict garden watering. Check the rules in your municipality before setting your timer." },
    de: { t: "Im Sommer gießen, ohne Wasser zu verschwenden",
      d: "Wann, wie viel und wie man den Garten im Sommer auf Mallorca gießt: selten und durchdringend, Tropfbewässerung, Mulch und Pflanzen nach Durst gruppiert.",
      intro: "Auf Mallorca ist Wasser knapp und der Sommer lang. Richtig gießen heißt nicht mehr gießen, sondern die passende Menge zur richtigen Zeit dorthin bringen, wo die Pflanze sie nutzt.",
      resumen: ["Im Morgengrauen oder am Abend gießen, nie in der prallen Sonne.", "Lieber selten und durchdringend als täglich ein wenig.", "Tropfbewässerung und eine Mulchschicht sparen viel Wasser.", "Pflanzen nach ihrem Wasserbedarf gruppieren."],
      pasos: [
        ["Die richtige Uhrzeit wählen", "Früh am Morgen oder gegen Abend gießen: mittags verdunstet ein großer Teil des Wassers, bevor es die Wurzeln erreicht. Am besten ist der frühe Morgen, weil die Blätter schnell abtrocknen und es weniger Pilzbefall gibt."],
        ["Seltener, aber gründlich gießen", "Eine lange Wassergabe alle paar Tage lockt die Wurzeln in die Tiefe, wo die Erde langsamer austrocknet. Täglich ein wenig Wasser hält sie an der Oberfläche und macht die Pflanze hitzeempfindlicher. Vor dem Gießen einen Finger in die Erde stecken: Ist sie in vier bis fünf Zentimetern Tiefe noch feucht, lieber warten."],
        ["Tropfbewässerung mit Zeitschaltuhr", "Tropfbewässerung bringt das Wasser an die Wurzel, ohne Wege oder Blätter zu benetzen. Mit einem Bewässerungscomputer wird in den frühen Morgenstunden gegossen, und die Minuten lassen sich Monat für Monat anpassen: im Juli und August mehr, im September schon weniger."],
        ["Den Boden abdecken", "Eine fünf bis acht Zentimeter dicke Schicht aus Pinienrinde, Kies oder gehäckseltem Schnittgut hält den Boden kühl, bremst die Verdunstung und unterdrückt Unkraut, das um Wasser konkurriert."],
        ["Pflanzen nach Durst gruppieren", "Genügsame Arten – Rosmarin, Lavendel, Mastixstrauch, Strauch-Gamander – in einen Bereich setzen, durstige in einen anderen, jeweils mit eigenem Bewässerungskreis. So bekommt keine zu viel oder zu wenig. Töpfe sind ein Sonderfall: Sie trocknen viel schneller aus als Gartenboden."],
      ],
      errores: ["Jeden Tag ein bisschen gießen, „zur Sicherheit“.", "Die Zeitschaltuhr das ganze Jahr gleich eingestellt lassen.", "Den Rasen mittags oder bei Wind bewässern."],
      nota: "In Dürrejahren schränken die Gemeinden die Gartenbewässerung ein. Vor dem Programmieren die Regeln der eigenen Gemeinde prüfen." } },

  { slug: "plantar-un-seto", meses: [10, 11, 12, 2, 3],
    plantas: ["Pistacia lentiscus", "Myrtus communis", "Pittosporum tobira", "Teucrium fruticans", "Westringia fruticosa", "Viburnum tinus", "Photinia × fraseri", "Rhamnus alaternus", "Laurus nobilis", "Cupressus sempervirens"],
    es: { t: "Cómo plantar un seto y cuál elegir",
      d: "Qué plantas de seto funcionan en Mallorca, cuándo plantarlas, a qué distancia y cómo cuidarlas el primer año para que cierren pronto.",
      intro: "Un seto da intimidad, corta el viento y enmarca el jardín. Elegir bien la planta y plantarla en la época adecuada ahorra agua, podas y disgustos durante años.",
      resumen: ["Planta en otoño: las lluvias hacen el trabajo de arraigo.", "Elige la especie según la altura que quieres y si llega el viento del mar.", "Deja entre 50 cm y 1 m entre plantas, según su tamaño.", "El primer verano necesita riego; después, mucho menos."],
      pasos: [
        ["Decide la altura y el estilo", "Para un seto bajo y recortado, de hasta un metro, sirven el mirto, la olivilla o el romero australiano. Para uno medio, el lentisco, el pitósporo, el durillo o la fotinia. Para una pantalla alta, el aladierno, el laurel o el ciprés. Cerca del mar, elige los que aguantan el salitre: pitósporo, lentisco, olivilla y romero australiano."],
        ["Planta en otoño", "De octubre a diciembre la tierra aún está templada y llegan las lluvias: la planta echa raíces todo el invierno y afronta su primer verano mucho más fuerte. La segunda mejor época es febrero y marzo."],
        ["Abre una zanja, no hoyos sueltos", "Cava una zanja de unos 40 cm de ancho y de hondo a lo largo de toda la línea y mezcla la tierra con compost o mantillo. Las raíces se extienden mejor que en hoyos individuales y el seto crece más parejo."],
        ["Respeta las distancias", "En setos bajos, dos o tres plantas por metro. En setos medios y altos, una planta cada 60 a 100 cm. Plantar más junto no cierra antes: las plantas compiten entre sí y acaban más débiles. Coloca el goteo antes de tapar."],
        ["Riega y despunta el primer año", "Riega bien al plantar y mantén el riego todo el primer verano. Corta las puntas un par de veces durante el primer año, aunque el seto aún sea bajo: así ramifica desde abajo y no queda pelado por la base."],
      ],
      errores: ["Plantar en pleno verano: la planta sufre y hay que regar el doble.", "Dejar que el seto suba sin despuntarlo: queda vacío por abajo.", "Mezclar en la misma línea especies con necesidades de agua muy distintas."] },
    ca: { t: "Com plantar una tanca vegetal i quina triar",
      d: "Quines plantes de tanca funcionen a Mallorca, quan plantar-les, a quina distància i com cuidar-les el primer any perquè tanquin aviat.",
      intro: "Una tanca vegetal dona intimitat, talla el vent i emmarca el jardí. Triar bé la planta i plantar-la a l'època adequada estalvia aigua, podes i disgusts durant anys.",
      resumen: ["Planta a la tardor: les pluges fan la feina d'arrelar.", "Tria l'espècie segons l'alçada que vols i si hi arriba el vent de la mar.", "Deixa entre 50 cm i 1 m entre plantes, segons la mida.", "El primer estiu necessita reg; després, molt menys."],
      pasos: [
        ["Decideix l'alçada i l'estil", "Per a una tanca baixa i retallada, de fins a un metre, serveixen la murta, l'olivereta o el romaní australià. Per a una de mitjana, la mata, el pitòspor, el marfull o la fotínia. Per a una pantalla alta, el llampúdol, el llorer o el xiprer. Prop de la mar, tria les que aguanten la salinitat: pitòspor, mata, olivereta i romaní australià."],
        ["Planta a la tardor", "D'octubre a desembre la terra encara és tèbia i arriben les pluges: la planta fa arrels tot l'hivern i afronta el primer estiu molt més forta. La segona millor època és febrer i març."],
        ["Obre una síquia, no clots separats", "Cava una síquia d'uns 40 cm d'ample i de fondària al llarg de tota la línia i mescla la terra amb compost o fems ben fets. Les arrels s'estenen millor que en clots individuals i la tanca creix més igualada."],
        ["Respecta les distàncies", "En tanques baixes, dues o tres plantes per metre. En tanques mitjanes i altes, una planta cada 60 a 100 cm. Plantar més junt no tanca abans: les plantes competeixen entre elles i acaben més febles. Col·loca el degoteig abans de tapar."],
        ["Rega i despunta el primer any", "Rega bé en plantar i mantén el reg tot el primer estiu. Talla les puntes un parell de vegades durant el primer any, encara que la tanca sigui baixa: així ramifica des de baix i no queda pelada per la base."],
      ],
      errores: ["Plantar en ple estiu: la planta pateix i s'ha de regar el doble.", "Deixar que la tanca pugi sense despuntar-la: queda buida per baix.", "Mesclar a la mateixa línia espècies amb necessitats d'aigua molt diferents."] },
    en: { t: "How to plant a hedge and which one to choose",
      d: "Which hedging plants work in Mallorca, when to plant them, how far apart and how to look after them in the first year so they fill in quickly.",
      intro: "A hedge gives privacy, breaks the wind and frames the garden. Choosing the right plant and planting at the right time saves water, pruning and disappointment for years.",
      resumen: ["Plant in autumn: the rains do the work of settling it in.", "Choose the species by the height you want and whether sea wind reaches it.", "Leave 50 cm to 1 m between plants, depending on their size.", "It needs watering through its first summer; far less after that."],
      pasos: [
        ["Decide on height and style", "For a low, clipped hedge up to a metre, myrtle, shrubby germander or coastal rosemary work well. For a medium one, mastic, Japanese mock orange, laurustinus or photinia. For a tall screen, Mediterranean buckthorn, bay laurel or cypress. Near the sea, choose those that stand up to salt spray: mock orange, mastic, shrubby germander and coastal rosemary."],
        ["Plant in autumn", "From October to December the soil is still warm and the rains arrive: the plant roots all winter and faces its first summer much stronger. The second-best time is February and March."],
        ["Dig a trench, not separate holes", "Dig a trench about 40 cm wide and deep along the whole line and mix the soil with compost. Roots spread more easily than from individual holes and the hedge grows more evenly."],
        ["Respect the spacing", "For low hedges, two or three plants per metre. For medium and tall hedges, one plant every 60 to 100 cm. Planting closer doesn't close the hedge sooner: the plants compete with each other and end up weaker. Lay the drip line before backfilling."],
        ["Water and tip-prune in the first year", "Water well at planting and keep watering through the first summer. Trim the tips a couple of times in the first year, even while the hedge is still short: it will branch from the bottom and not go bare at the base."],
      ],
      errores: ["Planting in high summer: the plant struggles and needs twice the water.", "Letting the hedge shoot up without tipping it: it ends up empty at the bottom.", "Mixing species with very different water needs in the same row."] },
    de: { t: "Eine Hecke pflanzen – und welche wählen",
      d: "Welche Heckenpflanzen auf Mallorca funktionieren, wann und in welchem Abstand man sie pflanzt und wie man sie im ersten Jahr pflegt, damit sie schnell dicht werden.",
      intro: "Eine Hecke schafft Sichtschutz, bricht den Wind und rahmt den Garten. Die richtige Pflanze zur richtigen Zeit gesetzt spart über Jahre Wasser, Schnittarbeit und Ärger.",
      resumen: ["Im Herbst pflanzen: Der Regen übernimmt das Anwachsen.", "Die Art nach gewünschter Höhe wählen – und danach, ob Seewind hinkommt.", "Je nach Größe 50 cm bis 1 m Abstand zwischen den Pflanzen lassen.", "Im ersten Sommer braucht sie Wasser, danach deutlich weniger."],
      pasos: [
        ["Höhe und Stil festlegen", "Für eine niedrige Formhecke bis einen Meter eignen sich Myrte, Strauch-Gamander oder Australischer Rosmarin. Für eine mittlere Mastixstrauch, Klebsame, Mittelmeer-Schneeball oder Glanzmispel. Für einen hohen Sichtschutz Immergrüner Kreuzdorn, Lorbeer oder Zypresse. In Meeresnähe salzverträgliche Arten wählen: Klebsame, Mastixstrauch, Strauch-Gamander und Australischen Rosmarin."],
        ["Im Herbst pflanzen", "Von Oktober bis Dezember ist der Boden noch warm und der Regen kommt: Die Pflanze wurzelt den ganzen Winter und geht viel kräftiger in ihren ersten Sommer. Die zweitbeste Zeit ist Februar und März."],
        ["Einen Graben ausheben, keine Einzellöcher", "Entlang der ganzen Linie einen etwa 40 cm breiten und tiefen Graben ausheben und die Erde mit Kompost mischen. Die Wurzeln breiten sich besser aus als in Einzellöchern, und die Hecke wächst gleichmäßiger."],
        ["Abstände einhalten", "Bei niedrigen Hecken zwei bis drei Pflanzen pro Meter. Bei mittleren und hohen Hecken eine Pflanze alle 60 bis 100 cm. Dichter pflanzen schließt die Hecke nicht schneller: Die Pflanzen konkurrieren miteinander und bleiben schwächer. Den Tropfschlauch vor dem Zuschütten verlegen."],
        ["Im ersten Jahr gießen und Spitzen kappen", "Beim Pflanzen gründlich wässern und den ganzen ersten Sommer weitergießen. Im ersten Jahr die Triebspitzen ein paar Mal kürzen, auch wenn die Hecke noch niedrig ist: So verzweigt sie sich von unten und verkahlt nicht an der Basis."],
      ],
      errores: ["Im Hochsommer pflanzen: Die Pflanze leidet und braucht doppelt so viel Wasser.", "Die Hecke in die Höhe schießen lassen, ohne die Spitzen zu kappen: Sie bleibt unten leer.", "Arten mit sehr unterschiedlichem Wasserbedarf in dieselbe Reihe setzen."] } },

  { slug: "picudo-rojo", meses: [3, 4, 5, 6, 7, 8, 9, 10],
    plantas: ["Phoenix canariensis", "Chamaerops humilis"],
    es: { t: "Picudo rojo: cómo proteger tus palmeras",
      d: "Cómo reconocer a tiempo el picudo rojo en las palmeras, qué tratamientos preventivos existen y por qué solo hay que podarlas en invierno.",
      intro: "El picudo rojo es un escarabajo cuyas larvas se comen la palmera por dentro. Cuando los daños se ven desde fuera, a menudo es tarde: por eso la clave es prevenir y revisar.",
      resumen: ["La palmera canaria es la más atacada; la datilera y otras, en menor medida.", "Los tratamientos preventivos periódicos son lo que de verdad protege.", "Poda solo en invierno y lo mínimo: los cortes atraen al insecto.", "Ante la primera señal, llama a un profesional: tratada a tiempo, puede salvarse."],
      pasos: [
        ["Aprende a reconocer las señales", "Hojas del centro caídas o torcidas, con la copa abierta como un paraguas; palmas con mordiscos en forma de punta de flecha; fibras masticadas, serrín húmedo o capullos de fibra entre las bases de las hojas, y a veces olor a fermentado. Mira la copa con calma cada pocas semanas, sobre todo de primavera a otoño."],
        ["Trata de forma preventiva", "Las palmeras sanas de zonas con picudo necesitan tratamientos periódicos durante los meses de calor: duchas sobre el cogollo con productos autorizados o con nematodos —unos gusanos microscópicos que parasitan a la larva—, o inyecciones en el tronco (endoterapia). Deben aplicarlos profesionales con carné, respetando los plazos de cada producto."],
        ["Poda solo en invierno", "El olor de los cortes frescos atrae al picudo desde lejos. Poda de diciembre a febrero, cuando el insecto está menos activo; quita solo las hojas secas y no «cepilles» el tronco. Conviene tratar los cortes después de podar."],
        ["Actúa rápido si hay síntomas", "No esperes a que la copa se venga abajo. Un profesional puede sanear la zona dañada y tratar la palmera; si el ataque se detecta pronto, muchas se recuperan."],
        ["No muevas los restos", "Las hojas y los trozos de una palmera afectada llevan larvas y adultos. No los dejes en el jardín ni los traslades por tu cuenta: lo correcto es que los triture o los retire una empresa especializada, para no extender la plaga a los vecinos."],
      ],
      errores: ["Podar en verano «para que esté bonita».", "Tratar una vez y olvidarse: la protección dura unas semanas.", "Dar por sana una palmera porque por fuera sigue verde."],
      nota: "Al palmito, la palmera autóctona, le afecta más la oruga Paysandisia que el picudo. Revísalo también." },
    ca: { t: "Morrut roig: com protegir les teves palmeres",
      d: "Com reconèixer a temps el morrut roig a les palmeres, quins tractaments preventius hi ha i per què només s'han de podar a l'hivern.",
      intro: "El morrut roig és un escarabat les larves del qual es mengen la palmera per dedins. Quan els danys es veuen des de fora, sovint ja és tard: per això la clau és prevenir i revisar.",
      resumen: ["La palmera canària és la més atacada; la datilera i d'altres, en menor mesura.", "Els tractaments preventius periòdics són el que de veres protegeix.", "Poda només a l'hivern i el mínim: els talls atreuen l'insecte.", "Al primer senyal, crida un professional: tractada a temps, es pot salvar."],
      pasos: [
        ["Aprèn a reconèixer els senyals", "Fulles del centre caigudes o tortes, amb la copa oberta com un paraigua; palmes amb mossegades en forma de punta de fletxa; fibres mastegades, serradures humides o capolls de fibra entre les bases de les fulles, i de vegades olor de fermentat. Mira la copa amb calma cada poques setmanes, sobretot de primavera a tardor."],
        ["Tracta de manera preventiva", "Les palmeres sanes de zones amb morrut necessiten tractaments periòdics durant els mesos de calor: dutxes sobre l'ull de la palmera amb productes autoritzats o amb nematodes —uns cucs microscòpics que parasiten la larva—, o injeccions al tronc (endoteràpia). Els han d'aplicar professionals amb carnet, respectant els terminis de cada producte."],
        ["Poda només a l'hivern", "L'olor dels talls frescs atreu el morrut des de lluny. Poda de desembre a febrer, quan l'insecte és menys actiu; lleva només les fulles seques i no «raspallis» el tronc. Convé tractar els talls després de podar."],
        ["Actua aviat si hi ha símptomes", "No esperis que la copa s'esfondri. Un professional pot sanejar la zona danyada i tractar la palmera; si l'atac es detecta prest, moltes es recuperen."],
        ["No moguis les restes", "Les fulles i els trossos d'una palmera afectada duen larves i adults. No els deixis al jardí ni els traslladis pel teu compte: el que toca és que els trituri o els retiri una empresa especialitzada, per no estendre la plaga als veïnats."],
      ],
      errores: ["Podar a l'estiu «perquè faci goig».", "Tractar una vegada i oblidar-se'n: la protecció dura unes setmanes.", "Donar per sana una palmera perquè per defora encara és verda."],
      nota: "Al garballó, la palmera autòctona, l'afecta més l'eruga Paysandisia que el morrut. Revisa'l també." },
    en: { t: "Red palm weevil: how to protect your palms",
      d: "How to spot red palm weevil in time, which preventive treatments exist and why palms should only be pruned in winter.",
      intro: "The red palm weevil is a beetle whose larvae eat the palm from the inside. By the time the damage shows on the outside it is often too late, so the key is prevention and regular checks.",
      resumen: ["The Canary Island date palm is the most attacked; date palms and others less so.", "Regular preventive treatments are what really protects them.", "Prune only in winter and as little as possible: cuts attract the insect.", "At the first sign, call a professional: treated in time, a palm can be saved."],
      pasos: [
        ["Learn to recognise the signs", "Central leaves drooping or twisted, with the crown opening out like an umbrella; fronds with arrowhead-shaped bites; chewed fibres, damp sawdust or fibre cocoons between the leaf bases, and sometimes a fermented smell. Take a careful look at the crown every few weeks, especially from spring to autumn."],
        ["Treat preventively", "Healthy palms in areas with weevil need regular treatments during the warm months: drenching the crown with authorised products or with nematodes — microscopic worms that parasitise the larvae — or trunk injections (endotherapy). These must be applied by licensed professionals, respecting each product's intervals."],
        ["Prune only in winter", "The smell of fresh cuts attracts the weevil from a distance. Prune from December to February, when the insect is least active; remove only dry fronds and don't “shave” the trunk. It is advisable to treat the cuts after pruning."],
        ["Act fast if there are symptoms", "Don't wait for the crown to collapse. A professional can clean out the damaged area and treat the palm; if the attack is caught early, many recover."],
        ["Don't move the remains", "The fronds and pieces of an affected palm carry larvae and adults. Don't leave them in the garden or transport them yourself: they should be shredded or removed by a specialist company, so the pest doesn't spread to the neighbours."],
      ],
      errores: ["Pruning in summer “to make it look nice”.", "Treating once and forgetting: protection lasts a few weeks.", "Assuming a palm is healthy because it still looks green from outside."],
      nota: "The dwarf fan palm, the native palm, is more affected by the Paysandisia moth caterpillar than by the weevil. Check it too." },
    de: { t: "Roter Palmrüssler: So schützen Sie Ihre Palmen",
      d: "Wie man den Roten Palmrüssler rechtzeitig erkennt, welche vorbeugenden Behandlungen es gibt und warum Palmen nur im Winter geschnitten werden sollten.",
      intro: "Der Rote Palmrüssler ist ein Käfer, dessen Larven die Palme von innen auffressen. Wenn die Schäden von außen sichtbar werden, ist es oft zu spät – deshalb kommt es auf Vorbeugung und Kontrolle an.",
      resumen: ["Die Kanarische Dattelpalme wird am häufigsten befallen, Dattelpalmen und andere seltener.", "Regelmäßige vorbeugende Behandlungen sind der wirksamste Schutz.", "Nur im Winter und so wenig wie möglich schneiden: Schnittstellen locken das Insekt an.", "Beim ersten Anzeichen einen Fachbetrieb rufen: Rechtzeitig behandelt, kann die Palme gerettet werden."],
      pasos: [
        ["Die Anzeichen erkennen", "Hängende oder verdrehte Herzblätter, die Krone klappt auf wie ein Regenschirm; Wedel mit pfeilspitzenförmigen Fraßstellen; zerkaute Fasern, feuchtes Bohrmehl oder Faserkokons zwischen den Blattbasen, manchmal ein gäriger Geruch. Die Krone alle paar Wochen in Ruhe ansehen, besonders von Frühling bis Herbst."],
        ["Vorbeugend behandeln", "Gesunde Palmen in Befallsgebieten brauchen in den warmen Monaten regelmäßige Behandlungen: Übergießen des Palmherzens mit zugelassenen Mitteln oder mit Nematoden – mikroskopisch kleinen Würmern, die die Larven parasitieren – oder Stamminjektionen (Endotherapie). Sie müssen von zugelassenen Fachleuten ausgeführt werden, unter Einhaltung der Fristen jedes Mittels."],
        ["Nur im Winter schneiden", "Der Geruch frischer Schnittstellen lockt den Käfer von weit her an. Von Dezember bis Februar schneiden, wenn das Insekt am wenigsten aktiv ist; nur trockene Wedel entfernen und den Stamm nicht „rasieren“. Die Schnittstellen sollten anschließend behandelt werden."],
        ["Bei Symptomen schnell handeln", "Nicht warten, bis die Krone zusammenbricht. Ein Fachbetrieb kann den befallenen Bereich säubern und die Palme behandeln; wird der Befall früh erkannt, erholen sich viele."],
        ["Reste nicht transportieren", "Wedel und Teile einer befallenen Palme enthalten Larven und Käfer. Nicht im Garten liegen lassen und nicht selbst wegfahren: Sie sollten von einem Fachbetrieb gehäckselt oder entsorgt werden, damit sich der Schädling nicht zu den Nachbarn ausbreitet."],
      ],
      errores: ["Im Sommer schneiden, „damit sie schön aussieht“.", "Einmal behandeln und es dann vergessen: Der Schutz hält nur einige Wochen.", "Eine Palme für gesund halten, weil sie von außen noch grün ist."],
      nota: "Die Zwergpalme, die heimische Palme, leidet stärker unter der Raupe des Palmenfalters Paysandisia als unter dem Rüssler. Auch sie kontrollieren." } },

  { slug: "poda-de-olivos-y-frutales", meses: [1, 2, 3],
    plantas: ["Olea europaea", "Olea europaea var. sylvestris", "Citrus × limon", "Citrus × sinensis", "Prunus dulcis", "Ficus carica", "Punica granatum", "Vitis vinifera"],
    es: { t: "Cómo podar olivos y frutales",
      d: "Cuándo y cómo podar el olivo, los cítricos, el almendro, la higuera y la parra en Mallorca: qué ramas quitar y qué errores evitar.",
      intro: "Podar no es cortar por cortar: es dejar entrar la luz y el aire para que el árbol dé mejor fruto y enferme menos. Con unas pocas reglas, cualquiera puede hacer una poda de mantenimiento correcta.",
      resumen: ["La mayoría se poda a final de invierno; el almendro, mejor en otoño.", "Quita primero lo seco, lo enfermo y lo que se cruza.", "Nunca más de un tercio de la copa de una vez.", "Desinfecta las herramientas entre árbol y árbol."],
      pasos: [
        ["Elige el momento", "Olivo: después de la cosecha y antes de que brote, de enero a marzo. Higuera, granado y parra: en pleno invierno, sin hojas. Almendro: en otoño, tras la caída de la hoja. Limonero y naranjo: una poda ligera a final de invierno o principio de primavera, pasado el frío. Evita podar con lluvia o con heladas a la vista."],
        ["Empieza por lo evidente", "Corta primero las ramas secas, rotas o enfermas. Después, los chupones —brotes verticales y muy vigorosos que salen del tronco o de las ramas gruesas— y las varetas que nacen del pie. Solo con eso, el árbol ya mejora mucho."],
        ["Abre el centro", "Elimina las ramas que crecen hacia dentro o que se cruzan y se rozan. En el olivo y en muchos frutales se busca una copa en forma de vaso, abierta por el centro, para que el sol llegue a todas las ramas. Una regla antigua dice que por un olivo bien podado tiene que poder pasar volando un pájaro."],
        ["Corta bien", "Haz cortes limpios junto al nacimiento de la rama, sin dañar el cuello —el pequeño engrosamiento de la base— y sin dejar tocones. En ramas gruesas, corta en tres tiempos para que no se desgarre la corteza. No quites más de un tercio de la copa en un año: una poda excesiva provoca una explosión de chupones."],
        ["Limpia y desinfecta", "Pasa alcohol o lejía diluida por tijeras y serruchos al cambiar de árbol: es la mejor defensa contra enfermedades como la Xylella, presente en Mallorca. Retira los restos de poda; si no están enfermos, triturados sirven de acolchado."],
      ],
      errores: ["Desmochar el árbol para bajarlo de golpe.", "Podar los cítricos tan fuerte como un olivo: necesitan muy poca poda.", "Dejar tocones o cortar a ras del tronco."] },
    ca: { t: "Com podar oliveres i fruiters",
      d: "Quan i com podar l'olivera, els cítrics, l'ametler, la figuera i la parra a Mallorca: quines branques llevar i quins errors evitar.",
      intro: "Podar no és tallar per tallar: és deixar entrar la llum i l'aire perquè l'arbre faci millor fruit i emmalalteixi menys. Amb unes poques regles, qualsevol pot fer una poda de manteniment correcta.",
      resumen: ["La majoria es poda a final d'hivern; l'ametler, millor a la tardor.", "Lleva primer el que és sec, malalt o s'encreua.", "Mai més d'un terç de la capçada d'una vegada.", "Desinfecta les eines entre arbre i arbre."],
      pasos: [
        ["Tria el moment", "Olivera: després de la collita i abans que broti, de gener a març. Figuera, magraner i parra: en ple hivern, sense fulles. Ametler: a la tardor, després de la caiguda de la fulla. Llimonera i taronger: una poda lleugera a final d'hivern o principi de primavera, passat el fred. Evita podar amb pluja o amb gelades a la vista."],
        ["Comença pel que és evident", "Talla primer les branques seques, rompudes o malaltes. Després, els xucladors —brots verticals i molt vigorosos que surten del tronc o de les branques gruixades— i els rebrots que neixen del peu. Només amb això, l'arbre ja millora molt."],
        ["Obre el centre", "Elimina les branques que creixen cap endins o que s'encreuen i es freguen. A l'olivera i a molts fruiters es cerca una capçada en forma de vas, oberta pel centre, perquè el sol arribi a totes les branques. Una regla antiga diu que per una olivera ben podada hi ha de poder passar volant un ocell."],
        ["Talla bé", "Fes talls nets vora el naixement de la branca, sense fer malbé el coll —el petit engruiximent de la base— i sense deixar monyons. A les branques gruixades, talla en tres temps perquè no s'esqueixi l'escorça. No llevis més d'un terç de la capçada en un any: una poda excessiva provoca una explosió de xucladors."],
        ["Neteja i desinfecta", "Passa alcohol o lleixiu diluït per les tisores i els xerracs en canviar d'arbre: és la millor defensa contra malalties com la Xylella, present a Mallorca. Retira les restes de poda; si no estan malaltes, triturades serveixen d'encoixinat."],
      ],
      errores: ["Escapçar l'arbre per abaixar-lo de cop.", "Podar els cítrics tan fort com una olivera: necessiten molt poca poda.", "Deixar monyons o tallar arran del tronc."] },
    en: { t: "How to prune olive and fruit trees",
      d: "When and how to prune olive, citrus, almond, fig and grapevine in Mallorca: which branches to remove and which mistakes to avoid.",
      intro: "Pruning isn't cutting for the sake of it: it lets in light and air so the tree fruits better and suffers less disease. With a few simple rules, anyone can do a sound maintenance prune.",
      resumen: ["Most are pruned in late winter; almond is best done in autumn.", "Start with what is dead, diseased or crossing.", "Never more than a third of the canopy at once.", "Disinfect your tools between one tree and the next."],
      pasos: [
        ["Choose the moment", "Olive: after harvest and before it sprouts, from January to March. Fig, pomegranate and grapevine: in midwinter, when leafless. Almond: in autumn, after leaf fall. Lemon and orange: a light prune in late winter or early spring, once the cold has passed. Avoid pruning in rain or when frost is forecast."],
        ["Start with the obvious", "First cut out dead, broken or diseased branches. Then the water shoots — vigorous upright shoots growing from the trunk or main branches — and the suckers at the base. That alone already does the tree a lot of good."],
        ["Open up the centre", "Remove branches that grow inwards or that cross and rub. In olives and many fruit trees the aim is a vase-shaped canopy, open in the middle, so that sunlight reaches every branch. An old rule says a bird should be able to fly through a well-pruned olive tree."],
        ["Cut properly", "Make clean cuts close to where the branch starts, without damaging the collar — the slight swelling at its base — and without leaving stubs. On thick branches, cut in three stages so the bark doesn't tear. Don't remove more than a third of the canopy in a year: over-pruning triggers a burst of water shoots."],
        ["Clean and disinfect", "Wipe secateurs and saws with alcohol or diluted bleach when moving to another tree: it is the best defence against diseases such as Xylella, which is present in Mallorca. Clear away the prunings; if they aren't diseased, shredded they make good mulch."],
      ],
      errores: ["Topping the tree to bring it down all at once.", "Pruning citrus as hard as an olive: they need very little pruning.", "Leaving stubs or cutting flush with the trunk."] },
    de: { t: "Oliven- und Obstbäume richtig schneiden",
      d: "Wann und wie man Olivenbaum, Zitrusbäume, Mandelbaum, Feige und Weinrebe auf Mallorca schneidet: welche Äste weg sollen und welche Fehler man vermeidet.",
      intro: "Schneiden heißt nicht einfach kürzen: Es geht darum, Licht und Luft in die Krone zu lassen, damit der Baum besser trägt und seltener krank wird. Mit wenigen Regeln gelingt ein ordentlicher Erhaltungsschnitt.",
      resumen: ["Die meisten schneidet man im Spätwinter, den Mandelbaum besser im Herbst.", "Zuerst entfernen, was trocken, krank oder sich kreuzend ist.", "Nie mehr als ein Drittel der Krone auf einmal.", "Werkzeug von Baum zu Baum desinfizieren."],
      pasos: [
        ["Den Zeitpunkt wählen", "Olivenbaum: nach der Ernte und vor dem Austrieb, von Januar bis März. Feige, Granatapfel und Weinrebe: mitten im Winter, ohne Laub. Mandelbaum: im Herbst, nach dem Laubfall. Zitrone und Orange: ein leichter Schnitt im Spätwinter oder zeitigen Frühjahr, wenn die Kälte vorbei ist. Nicht bei Regen oder drohendem Frost schneiden."],
        ["Mit dem Offensichtlichen beginnen", "Zuerst trockene, gebrochene oder kranke Äste herausnehmen. Dann die Wasserschosse – kräftige, senkrechte Triebe aus Stamm oder starken Ästen – und die Stockausschläge am Fuß. Schon das tut dem Baum sehr gut."],
        ["Die Mitte öffnen", "Äste entfernen, die nach innen wachsen oder sich kreuzen und reiben. Beim Olivenbaum und vielen Obstbäumen strebt man eine becherförmige, in der Mitte offene Krone an, damit die Sonne alle Äste erreicht. Eine alte Regel sagt: Durch einen gut geschnittenen Olivenbaum muss ein Vogel hindurchfliegen können."],
        ["Sauber schneiden", "Glatte Schnitte direkt am Astansatz setzen, ohne den Astring – die kleine Verdickung an der Basis – zu verletzen und ohne Stummel stehen zu lassen. Dicke Äste in drei Schritten absägen, damit die Rinde nicht einreißt. Nicht mehr als ein Drittel der Krone pro Jahr entfernen: Zu starker Schnitt führt zu einer Flut von Wasserschossen."],
        ["Reinigen und desinfizieren", "Scheren und Sägen beim Wechsel zum nächsten Baum mit Alkohol oder verdünnter Bleichlauge abwischen: der beste Schutz gegen Krankheiten wie Xylella, die es auf Mallorca gibt. Schnittgut entfernen; ist es gesund, eignet es sich gehäckselt als Mulch."],
      ],
      errores: ["Den Baum kappen, um ihn auf einmal niedriger zu machen.", "Zitrusbäume so stark schneiden wie einen Olivenbaum: Sie brauchen sehr wenig Schnitt.", "Stummel stehen lassen oder bündig am Stamm schneiden."] } },

  { slug: "terraza-con-sol-y-viento", meses: [3, 4, 5, 10, 11],
    plantas: ["Olea europaea", "Chamaerops humilis", "Pittosporum tobira", "Teucrium fruticans", "Salvia rosmarinus", "Lavandula angustifolia / dentata", "Westringia fruticosa", "Gazania rigens", "Tulbaghia violacea", "Aloe vera", "Crassula ovata"],
    es: { t: "Qué plantar en una terraza con sol y viento",
      d: "Plantas que aguantan el sol, el viento y el salitre en terrazas y áticos de Mallorca, y cómo elegir macetas, tierra y riego para que duren.",
      intro: "Una terraza al sol y al viento es el sitio más duro para una planta: la maceta se recalienta, la tierra se seca en horas y el aire quema las hojas. Con las especies adecuadas y macetas grandes, puede estar verde todo el año.",
      resumen: ["Elige plantas mediterráneas y suculentas: están hechas a este clima.", "Macetas grandes y pesadas: se secan más despacio y no vuelcan.", "Goteo con programador: en verano las macetas piden agua a menudo.", "Cubre la tierra con grava o corteza."],
      pasos: [
        ["Elige plantas duras", "Para dar altura: olivo, palmito, pitósporo u olivilla. Para llenar: romero, lavanda y romero australiano. Para dar color: gazania y tulbalgia. Y para los rincones más castigados, suculentas como el aloe o el árbol de jade. Todas aguantan sol, viento y algún olvido de riego."],
        ["Macetas grandes: mejor pocas y buenas", "Cuanta más tierra, más reserva de agua y menos calor en las raíces. Para arbustos, macetas de 40 cm de diámetro como mínimo; para un olivo o un palmito, de 60 cm o más. El barro y la piedra pesan y aíslan mejor que el plástico oscuro. Comprueba que tengan agujeros de drenaje y, en áticos, ten en cuenta el peso: una maceta grande recién regada pesa mucho."],
        ["Tierra que drene", "Usa un sustrato de calidad aligerado con perlita o arena gruesa. La tierra del jardín sola se apelmaza en la maceta y ahoga las raíces."],
        ["Automatiza el riego", "En julio y agosto una maceta al sol puede necesitar agua cada día o cada dos. Un programador con goteo —los hay de pilas, para un grifo normal— riega de madrugada y te deja irte de vacaciones tranquilo."],
        ["Protege la tierra y agrupa", "Cubre la superficie con grava o corteza para que no se seque ni vuele con el viento. Agrupa las macetas: se dan sombra y humedad unas a otras. Las plantas altas, bien sujetas con un tutor o arrimadas a una pared."],
      ],
      errores: ["Macetas pequeñas y negras a pleno sol: cuecen las raíces.", "Platos con agua estancada bajo la maceta: pudren la raíz y crían mosquitos.", "Plantas de sombra o de hoja tierna, como hortensias y helechos, en primera línea."] },
    ca: { t: "Què plantar en una terrassa amb sol i vent",
      d: "Plantes que aguanten el sol, el vent i la salinitat en terrasses i àtics de Mallorca, i com triar tests, terra i reg perquè durin.",
      intro: "Una terrassa al sol i al vent és el lloc més dur per a una planta: el test s'escalfa, la terra s'asseca en hores i l'aire crema les fulles. Amb les espècies adequades i tests grans, pot estar verda tot l'any.",
      resumen: ["Tria plantes mediterrànies i suculentes: estan fetes a aquest clima.", "Tests grans i pesants: s'assequen més a poc a poc i no bolquen.", "Degoteig amb programador: a l'estiu els tests demanen aigua sovint.", "Cobreix la terra amb grava o escorça."],
      pasos: [
        ["Tria plantes dures", "Per donar alçada: olivera, garballó, pitòspor o olivereta. Per omplir: romaní, lavanda i romaní australià. Per donar color: gazània i tulbàgia. I per als racons més castigats, suculentes com l'àloe o l'arbre de jade. Totes aguanten sol, vent i qualque oblit de reg."],
        ["Tests grans: millor pocs i bons", "Com més terra, més reserva d'aigua i menys calor a les arrels. Per a arbusts, tests de 40 cm de diàmetre com a mínim; per a una olivera o un garballó, de 60 cm o més. El fang i la pedra pesen i aïllen millor que el plàstic fosc. Comprova que tenguin forats de drenatge i, als àtics, tingues en compte el pes: un test gran acabat de regar pesa molt."],
        ["Terra que dreni", "Empra un substrat de qualitat alleugerit amb perlita o arena gruixada. La terra del jardí tota sola s'atapeeix dins el test i ofega les arrels."],
        ["Automatitza el reg", "Al juliol i a l'agost un test al sol pot necessitar aigua cada dia o cada dos. Un programador amb degoteig —n'hi ha de piles, per a una aixeta normal— rega de matinada i et deixa anar de vacances tranquil."],
        ["Protegeix la terra i agrupa", "Cobreix la superfície amb grava o escorça perquè no s'assequi ni voli amb el vent. Agrupa els tests: es fan ombra i humitat uns als altres. Les plantes altes, ben subjectes amb un tutor o arrambades a una paret."],
      ],
      errores: ["Tests petits i negres a ple sol: couen les arrels.", "Plats amb aigua estancada davall el test: podreixen l'arrel i crien moscards.", "Plantes d'ombra o de fulla tendra, com hortènsies i falgueres, a primera línia."] },
    en: { t: "What to plant on a sunny, windy terrace",
      d: "Plants that cope with sun, wind and salt on terraces and penthouses in Mallorca, and how to choose pots, compost and irrigation so they last.",
      intro: "A terrace in full sun and wind is the toughest place for a plant: the pot overheats, the compost dries out in hours and the air scorches the leaves. With the right species and large pots, it can be green all year.",
      resumen: ["Choose Mediterranean plants and succulents: they are made for this climate.", "Large, heavy pots: they dry out more slowly and don't blow over.", "Drip irrigation on a timer: in summer pots need water often.", "Cover the compost with gravel or bark."],
      pasos: [
        ["Choose tough plants", "For height: olive, dwarf fan palm, Japanese mock orange or shrubby germander. For filling out: rosemary, lavender and coastal rosemary. For colour: gazania and society garlic. And for the most exposed corners, succulents such as aloe or jade plant. All of them take sun, wind and the odd missed watering."],
        ["Large pots: fewer but better", "The more compost, the bigger the water reserve and the cooler the roots. For shrubs, pots at least 40 cm across; for an olive or a fan palm, 60 cm or more. Terracotta and stone are heavier and insulate better than dark plastic. Check they have drainage holes and, on penthouses, bear the weight in mind: a large pot that has just been watered is very heavy."],
        ["Free-draining compost", "Use good-quality compost lightened with perlite or coarse sand. Garden soil on its own compacts in a pot and suffocates the roots."],
        ["Automate the watering", "In July and August a pot in the sun may need water every day or two. A drip system on a timer — battery-powered ones fit an ordinary tap — waters before dawn and lets you go on holiday with peace of mind."],
        ["Protect the surface and group the pots", "Cover the surface with gravel or bark so it neither dries out nor blows away. Group the pots together: they give each other shade and humidity. Tall plants should be well staked or set against a wall."],
      ],
      errores: ["Small black pots in full sun: they cook the roots.", "Saucers of standing water under the pot: they rot the roots and breed mosquitoes.", "Shade plants or soft-leaved ones, such as hydrangeas and ferns, in the front line."] },
    de: { t: "Was auf einer sonnigen, windigen Terrasse wächst",
      d: "Pflanzen, die auf Terrassen und Dachterrassen Mallorcas Sonne, Wind und Salz aushalten – und wie man Töpfe, Erde und Bewässerung wählt, damit sie lange halten.",
      intro: "Eine Terrasse in Sonne und Wind ist der härteste Standort für eine Pflanze: Der Topf heizt sich auf, die Erde trocknet in Stunden aus, und die Luft verbrennt die Blätter. Mit den richtigen Arten und großen Töpfen bleibt sie das ganze Jahr grün.",
      resumen: ["Mediterrane Pflanzen und Sukkulenten wählen: Sie sind für dieses Klima gemacht.", "Große, schwere Töpfe: Sie trocknen langsamer aus und kippen nicht um.", "Tropfbewässerung mit Zeitschaltuhr: Im Sommer brauchen Töpfe oft Wasser.", "Die Erde mit Kies oder Rinde abdecken."],
      pasos: [
        ["Robuste Pflanzen wählen", "Für Höhe: Olivenbaum, Zwergpalme, Klebsame oder Strauch-Gamander. Zum Auffüllen: Rosmarin, Lavendel und Australischer Rosmarin. Für Farbe: Gazanie und Zimmerknoblauch. Und für die härtesten Ecken Sukkulenten wie Aloe oder Geldbaum. Alle vertragen Sonne, Wind und auch einmal vergessenes Gießen."],
        ["Große Töpfe: lieber wenige und gute", "Je mehr Erde, desto größer der Wasservorrat und desto kühler die Wurzeln. Für Sträucher Töpfe mit mindestens 40 cm Durchmesser, für einen Olivenbaum oder eine Zwergpalme 60 cm oder mehr. Ton und Stein sind schwerer und isolieren besser als dunkler Kunststoff. Auf Abzugslöcher achten und auf Dachterrassen das Gewicht bedenken: Ein großer, frisch gegossener Topf ist sehr schwer."],
        ["Durchlässige Erde", "Hochwertiges Substrat verwenden, aufgelockert mit Perlit oder grobem Sand. Reine Gartenerde verdichtet sich im Topf und erstickt die Wurzeln."],
        ["Die Bewässerung automatisieren", "Im Juli und August kann ein Topf in der Sonne jeden oder jeden zweiten Tag Wasser brauchen. Eine Tropfbewässerung mit Zeitschaltuhr – es gibt batteriebetriebene für den normalen Wasserhahn – gießt früh am Morgen und lässt Sie beruhigt in den Urlaub fahren."],
        ["Erde schützen und Töpfe gruppieren", "Die Oberfläche mit Kies oder Rinde abdecken, damit sie weder austrocknet noch vom Wind weggeweht wird. Töpfe zusammenstellen: Sie spenden einander Schatten und Feuchtigkeit. Hohe Pflanzen gut anbinden oder an eine Wand stellen."],
      ],
      errores: ["Kleine schwarze Töpfe in der prallen Sonne: Sie kochen die Wurzeln.", "Untersetzer mit stehendem Wasser: Sie lassen die Wurzeln faulen und ziehen Mücken an.", "Schattenpflanzen oder zartblättrige Arten wie Hortensien und Farne in vorderster Reihe."] } },

  { slug: "recuperar-el-cesped", meses: [9, 10, 11],
    plantas: ["Gazania rigens", "Tulbaghia violacea", "Osteospermum ecklonis"],
    es: { t: "Cómo recuperar el césped después del verano",
      d: "Paso a paso para recuperar un césped con calvas tras el verano en Mallorca: escarificar, airear, resembrar, recebar y abonar en otoño.",
      intro: "El calor, la falta de agua y el pisoteo dejan el césped amarillo y con calvas. El otoño es el mejor momento para recuperarlo: la tierra sigue templada, llueve y las malas hierbas aflojan.",
      resumen: ["Hazlo entre mediados de septiembre y noviembre.", "Escarifica y airea antes de sembrar: la semilla tiene que tocar tierra.", "Mantén la siembra húmeda hasta que nazca.", "Si se repite cada verano, plantéate reducir el césped."],
      pasos: [
        ["Siega bajo y escarifica", "Corta el césped algo más bajo de lo habitual y pasa con energía el escarificador o un rastrillo de púas para sacar el fieltro: esa capa de restos secos que impide que el agua y la semilla lleguen a la tierra. Recoge todo lo que salga."],
        ["Airea las zonas duras", "Donde la tierra esté apelmazada por el paso, pínchala con una horca o un aireador cada 10 o 15 cm. El agua y el aire volverán a entrar y las raíces podrán profundizar."],
        ["Resiembra las calvas", "Reparte semilla de la misma mezcla que tu césped, o de una resistente a la sequía, sobre las zonas ralas —unos 30 gramos, un puñado, por metro cuadrado— y rastrilla suavemente para que quede en contacto con la tierra."],
        ["Recebo y abono", "Cubre con una capa fina, de menos de un centímetro, de recebo (mezcla de arena y mantillo) y pasa un rodillo o pisa con una tabla. Abona con un abono de otoño, rico en potasio, que fortalece las raíces de cara al invierno."],
        ["Riega poco y a menudo hasta que nazca", "Durante dos o tres semanas, da riegos cortos una o dos veces al día para que la semilla no se seque. Cuando la hierba nueva alcance unos 8 cm, haz la primera siega, alta, y vuelve poco a poco a los riegos largos y espaciados."],
      ],
      errores: ["Resembrar encima del fieltro sin escarificar: la semilla no arraiga.", "Dejar secar la siembra un solo día de calor.", "Segar muy corto en verano: el césped alto sombrea la tierra y gasta menos agua."],
      nota: "¿Calvas todos los años en el mismo sitio? Quizá ese rincón no es para césped: las tapizantes de bajo consumo cubren el suelo con mucha menos agua." },
    ca: { t: "Com recuperar la gespa després de l'estiu",
      d: "Pas a pas per recuperar una gespa amb clapes després de l'estiu a Mallorca: escarificar, airejar, tornar a sembrar, encatifar i adobar a la tardor.",
      intro: "La calor, la manca d'aigua i el trepig deixen la gespa groga i amb clapes. La tardor és el millor moment per recuperar-la: la terra encara és tèbia, plou i les males herbes afluixen.",
      resumen: ["Fes-ho entre mitjan setembre i novembre.", "Escarifica i aireja abans de sembrar: la llavor ha de tocar terra.", "Mantén la sembra humida fins que neixi.", "Si es repeteix cada estiu, planteja't reduir la gespa."],
      pasos: [
        ["Sega baix i escarifica", "Talla la gespa un poc més baixa del que és habitual i passa amb energia l'escarificador o un rampí de pues per treure el feltre: aquesta capa de restes seques que impedeix que l'aigua i la llavor arribin a la terra. Recull tot el que surti."],
        ["Aireja les zones dures", "Allà on la terra estigui atapeïda pel pas, punxa-la amb una forca o un airejador cada 10 o 15 cm. L'aigua i l'aire hi tornaran a entrar i les arrels podran aprofundir."],
        ["Torna a sembrar les clapes", "Reparteix llavor de la mateixa mescla que la teva gespa, o d'una de resistent a la sequera, sobre les zones clares —uns 30 grams, un grapat, per metre quadrat— i passa el rampí suaument perquè quedi en contacte amb la terra."],
        ["Encatifat i adob", "Cobreix amb una capa fina, de menys d'un centímetre, d'encatifat (mescla d'arena i fems ben fets) i passa-hi un corró o trepitja amb una post. Adoba amb un adob de tardor, ric en potassi, que enforteix les arrels de cara a l'hivern."],
        ["Rega poc i sovint fins que neixi", "Durant dues o tres setmanes, fes regs curts una o dues vegades al dia perquè la llavor no s'assequi. Quan l'herba nova arribi a uns 8 cm, fes la primera sega, alta, i torna a poc a poc als regs llargs i espaiats."],
      ],
      errores: ["Sembrar damunt el feltre sense escarificar: la llavor no arrela.", "Deixar assecar la sembra un sol dia de calor.", "Segar molt curt a l'estiu: la gespa alta fa ombra a la terra i gasta menys aigua."],
      nota: "Clapes cada any al mateix lloc? Potser aquell racó no és per a gespa: les entapissants de baix consum cobreixen el sòl amb molta menys aigua." },
    en: { t: "How to revive your lawn after the summer",
      d: "Step by step to revive a patchy lawn after the summer in Mallorca: scarify, aerate, overseed, top-dress and feed in autumn.",
      intro: "Heat, lack of water and foot traffic leave the lawn yellow and patchy. Autumn is the best time to revive it: the soil is still warm, the rain returns and weeds ease off.",
      resumen: ["Do it between mid-September and November.", "Scarify and aerate before sowing: seed has to touch soil.", "Keep the sown areas moist until they germinate.", "If it happens every summer, think about having less lawn."],
      pasos: [
        ["Mow low and scarify", "Cut the lawn a little lower than usual and go over it vigorously with a scarifier or a spring-tine rake to pull out the thatch: the layer of dead material that stops water and seed reaching the soil. Collect everything that comes out."],
        ["Aerate the hard areas", "Where the soil is compacted by foot traffic, spike it with a garden fork or an aerator every 10 to 15 cm. Water and air will get back in and the roots will be able to go deeper."],
        ["Overseed the bare patches", "Scatter seed of the same mix as your lawn, or a drought-tolerant one, over the thin areas — about 30 grams, a handful, per square metre — and rake lightly so it is in contact with the soil."],
        ["Top-dress and feed", "Cover with a thin layer, less than a centimetre, of top-dressing (a mix of sand and fine compost) and roll it or firm it with a board. Apply an autumn lawn feed, high in potassium, which strengthens the roots ahead of winter."],
        ["Water little and often until it germinates", "For two or three weeks, give short waterings once or twice a day so the seed doesn't dry out. When the new grass reaches about 8 cm, give it its first cut, on a high setting, and gradually go back to long, spaced-out waterings."],
      ],
      errores: ["Overseeding on top of thatch without scarifying: the seed doesn't take.", "Letting the sown area dry out for even one hot day.", "Mowing very short in summer: taller grass shades the soil and uses less water."],
      nota: "Bare patches in the same place every year? Perhaps that corner isn't meant for lawn: low-water ground covers carpet the soil with far less water." },
    de: { t: "Den Rasen nach dem Sommer wieder aufbauen",
      d: "Schritt für Schritt einen lückigen Rasen nach dem Sommer auf Mallorca erneuern: vertikutieren, lüften, nachsäen, besanden und im Herbst düngen.",
      intro: "Hitze, Wassermangel und Tritt hinterlassen einen gelben, lückigen Rasen. Der Herbst ist die beste Zeit, ihn zu erneuern: Der Boden ist noch warm, der Regen kommt zurück, und das Unkraut lässt nach.",
      resumen: ["Zwischen Mitte September und November erledigen.", "Vor der Aussaat vertikutieren und lüften: Das Saatgut braucht Bodenkontakt.", "Die Nachsaat feucht halten, bis sie aufgeht.", "Wiederholt es sich jeden Sommer, über weniger Rasen nachdenken."],
      pasos: [
        ["Tief mähen und vertikutieren", "Den Rasen etwas kürzer als üblich mähen und kräftig mit dem Vertikutierer oder einem Federrechen durchgehen, um den Rasenfilz herauszuholen: die Schicht aus abgestorbenem Material, die Wasser und Saatgut vom Boden fernhält. Alles zusammenrechen, was herauskommt."],
        ["Verdichtete Stellen lüften", "Wo der Boden durch Tritt verdichtet ist, alle 10 bis 15 cm mit einer Grabegabel oder einem Aerifizierer einstechen. Wasser und Luft dringen wieder ein, und die Wurzeln können tiefer wachsen."],
        ["Kahle Stellen nachsäen", "Saatgut derselben Mischung wie der Rasen – oder eine trockenheitsverträgliche – auf die lückigen Stellen streuen, etwa 30 Gramm (eine Handvoll) pro Quadratmeter, und leicht einharken, damit es Bodenkontakt hat."],
        ["Besanden und düngen", "Mit einer dünnen Schicht von weniger als einem Zentimeter aus Sand und feinem Kompost abdecken und anwalzen oder mit einem Brett festtreten. Einen kaliumbetonten Herbstrasendünger ausbringen, der die Wurzeln für den Winter stärkt."],
        ["Bis zum Aufgehen wenig, aber oft gießen", "Zwei bis drei Wochen lang ein- bis zweimal täglich kurz wässern, damit das Saatgut nicht austrocknet. Wenn das neue Gras etwa 8 cm hoch ist, zum ersten Mal mähen – hoch eingestellt – und nach und nach wieder zu langen, seltenen Wassergaben übergehen."],
      ],
      errores: ["Auf den Filz nachsäen, ohne zu vertikutieren: Das Saatgut wächst nicht an.", "Die Nachsaat auch nur einen heißen Tag austrocknen lassen.", "Im Sommer sehr kurz mähen: Höheres Gras beschattet den Boden und verbraucht weniger Wasser."],
      nota: "Jedes Jahr kahle Stellen am selben Ort? Vielleicht ist diese Ecke nichts für Rasen: genügsame Bodendecker begrünen den Boden mit viel weniger Wasser." } },
];

